# BSP tree: split leaves, resize ratios, close merges
class Leaf:
    def __init__(self, name):
        self.name = name
class Split:
    def __init__(self, a, b, vertical=True, ratio=0.5):
        self.a, self.b, self.vertical, self.ratio = a, b, vertical, ratio

def layout(node, x=0, y=0, w=80, h=24, out=None):
    out = out if out is not None else {}
    if isinstance(node, Leaf):
        out[node.name] = (x, y, w, h)
    else:
        if node.vertical:
            layout(node.a, x, y, int(w*node.ratio), h, out)
            layout(node.b, x+int(w*node.ratio), y, w-int(w*node.ratio), h, out)
        else:
            layout(node.a, x, y, w, int(h*node.ratio), out)
            layout(node.b, x, y+int(h*node.ratio), w, h-int(h*node.ratio), out)
    return out

root = Split(Leaf('editor'), Split(Leaf('terminal'), Leaf('docs'), vertical=False), vertical=True)
for name, box in layout(root).items():
    print('%-9s x=%d y=%d w=%d h=%d' % (name, *box))

# editor groups: independent tab strips, drag tabs between them
groups = {
    'left': {'tabs': ['main.py', 'util.py'], 'active': 'main.py'},
    'right': {'tabs': ['test.py'], 'active': 'test.py'},
}

def move_tab(tab, src, dst):
    groups[src]['tabs'].remove(tab)
    groups[dst]['tabs'].append(tab)
    groups[dst]['active'] = tab
    if groups[src]['active'] == tab:
        groups[src]['active'] = groups[src]['tabs'][0] if groups[src]['tabs'] else None

move_tab('util.py', 'left', 'right')
for g, s in groups.items():
    print('%-6s tabs=%s active=%s' % (g, s['tabs'], s['active']))

# 5 drop zones per pane: left/right/top/bottom/center
def zone(px, py, x, y, w, h):
    cx, cy = x + w/2, y + h/2
    dx, dy = (px - cx) / (w/2), (py - cy) / (h/2)
    if abs(dx) < 0.4 and abs(dy) < 0.4:
        return 'center (tab)'
    return max([('left', -dx), ('right', dx), ('top', -dy), ('bottom', dy)],
               key=lambda t: t[1])[0] + ' (split)'

for px, py in ((10, 50), (90, 50), (50, 10), (50, 50)):
    print('pointer (%d,%d) -> drop %s' % (px, py, zone(px, py, 0, 0, 100, 100)))
print('ghost preview shows the resulting split before drop')

# directional focus: nearest pane rect in the given direction
panes = {'editor': (0, 0, 50, 24), 'term': (50, 0, 30, 24), 'docs': (50, 12, 30, 12)}

def center(r):
    x, y, w, h = r
    return (x + w/2, y + h/2)

def focus_dir(cur, dx, dy):
    cx, cy = center(panes[cur])
    best, bd = None, 1e9
    for name, r in panes.items():
        if name == cur:
            continue
        x, y = center(r)
        vx, vy = x - cx, y - cy
        if vx*dx + vy*dy > 0:  # in the requested half-plane
            d = vx*vx + vy*vy
            if d < bd:
                best, bd = name, d
    return best

print('from editor, focus right ->', focus_dir('editor', 1, 0))
print('from term, focus down ->', focus_dir('term', 0, 1))

# one keystroke, cursors in two panes apply it independently
panes = {'a.py': list('foo = 1'), 'b.py': list('foo = 2')}
cursors = {'a.py': [0], 'b.py': [0]}  # caret positions per pane

def type_char(ch):
    for pane, carets in cursors.items():
        for c in sorted(carets, reverse=True):
            panes[pane].insert(c, ch)
        cursors[pane] = [c + 1 for c in carets]

type_char('X')
for p, chars in panes.items():
    print('%-5s -> %s' % (p, ''.join(chars)))
print('broadcast edits; per-pane cursors and undo')

# per-pane budget: virtualize the inactive, keep state cheap
panes = [{'id': i, 'visible': i < 3, 'heavy': None} for i in range(8)]

def activate(p):
    if p['heavy'] is None:
        p['heavy'] = 'editor-instance-%d' % p['id']  # expensive

def deactivate(p):
    p['heavy'] = None  # drop heavy resources, keep state

for p in panes:
    (activate if p['visible'] else deactivate)(p)
active = sum(1 for p in panes if p['heavy'])
print('%d panes open, %d heavy instances (visible only)' % (len(panes), active))
print('state is cheap; editor instances are the budget')
